                                                                                                                                                                                                                   
  CREATE TABLE "STS_FILE"                                                                                                                                                                                
   (	"FILE_ID" NUMBER(20,0) GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"ROOT_FOLDER_ID" NUMBER(20,0),                                                                                                                                                                                    
	"PARENT_FOLDER_ID" NUMBER(20,0),                                                                                                                                                                                  
	"FILE_NAME" VARCHAR2(500),                                                                                                                                                                                        
	"FILE_FORMAT" VARCHAR2(500),                                                                                                                                                                                      
	"FILE_STATUS" VARCHAR2(255) DEFAULT 'NORMAL',                                                                                                                                                                     
	"FILE_URL" VARCHAR2(2000),                                                                                                                                                                                        
	"FILE_TYPE" VARCHAR2(255),                                                                                                                                                                                        
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                                 
	"DEL_DATE" DATE,                                                                                                                                                                                                  
	"UPLOAD_DATE" DATE,                                                                                                                                                                                               
	"PLANS_FILE_TYPE" VARCHAR2(20),                                                                                                                                                                                   
	"PLANS_FILE_DATE" DATE,                                                                                                                                                                                           
	"ACTUAL_FILE_DATE" DATE,                                                                                                                                                                                          
	"REMARK" VARCHAR2(500),                                                                                                                                                                                           
	"TENANT_ID" NUMBER(20,0),                                                                                                                                                                                         
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                        
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                             
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                        
	"UPDATE_DATE" DATE DEFAULT sysdate,                                                                                                                                                                               
	"SCOPE_TYPE" NVARCHAR2(20),                                                                                                                                                                                       
	"FILE_CONTENT" CLOB,                                                                                                                                                                                              
	"FILE_SIZE" NUMBER(20,0),                                                                                                                                                                                         
	"FILE_VERSION_TAG" VARCHAR2(255),                                                                                                                                                                                 
	"FILE_PATH" VARCHAR2(4000),                                                                                                                                                                                       
	"FILE_LEVEL" NUMBER(20,0),                                                                                                                                                                                        
	"IS_PERMISSION_CHANGES" NUMBER(10,0) DEFAULT 0,                                                                                                                                                                   
	"ENGLISH_NAME" VARCHAR2(500),                                                                                                                                                                                     
	"UPLOADER_DING_ID" VARCHAR2(512),                                                                                                                                                                                 
	"ADD_METHOD" VARCHAR2(64) DEFAULT null,                                                                                                                                                                           
	"SYSTEM_ID" NUMBER(20,0),                                                                                                                                                                                         
	"NEED_SYNC" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                                
	"SORT_NUM" NUMBER(10,0) DEFAULT 1,                                                                                                                                                                                
	 PRIMARY KEY ("FILE_ID")                                                                                                                                                                                          
  USING INDEX  ENABLE,                                                                                                                                                                                             
	 CONSTRAINT "STS_FILE_NEED_SYNC_CK" CHECK (need_sync in (0, 1)) ENABLE                                                                                                                                            
   ) ;                                                                                                                                                                                                             

